#[cfg(test)]
mod tests {
    use std::{collections::HashSet, fs, path::Path};

    use super::*;

    #[test]
    fn debug_subscription_catalog_preserves_vanilla_registration_order() {
        assert_eq!(VANILLA_DEBUG_SUBSCRIPTION_TYPES.len(), 16);
        assert_eq!(
            VANILLA_DEBUG_SUBSCRIPTION_TYPES
                .iter()
                .map(|entry| (entry.constant_name, entry.resource_id))
                .collect::<Vec<_>>(),
            vec![
                (
                    "DEDICATED_SERVER_TICK_TIME",
                    "minecraft:dedicated_server_tick_time"
                ),
                ("BEES", "minecraft:bees"),
                ("BRAINS", "minecraft:brains"),
                ("BREEZES", "minecraft:breezes"),
                ("GOAL_SELECTORS", "minecraft:goal_selectors"),
                ("ENTITY_PATHS", "minecraft:entity_paths"),
                (
                    "ENTITY_BLOCK_INTERSECTIONS",
                    "minecraft:entity_block_intersections"
                ),
                ("BEE_HIVES", "minecraft:bee_hives"),
                ("POIS", "minecraft:pois"),
                (
                    "REDSTONE_WIRE_ORIENTATIONS",
                    "minecraft:redstone_wire_orientations"
                ),
                ("VILLAGE_SECTIONS", "minecraft:village_sections"),
                ("RAIDS", "minecraft:raids"),
                ("STRUCTURES", "minecraft:structures"),
                ("GAME_EVENT_LISTENERS", "minecraft:game_event_listeners"),
                ("NEIGHBOR_UPDATES", "minecraft:neighbor_updates"),
                ("GAME_EVENTS", "minecraft:game_events"),
            ]
        );
        let mut resource_ids = HashSet::new();
        for (expected_id, entry) in VANILLA_DEBUG_SUBSCRIPTION_TYPES.iter().enumerate() {
            assert_eq!(entry.id, expected_id as i32);
            assert!(resource_ids.insert(entry.resource_id));
            assert_eq!(vanilla_debug_subscription_type_by_id(entry.id), Some(entry));
            assert_eq!(
                vanilla_debug_subscription_type_by_resource_id(entry.resource_id),
                Some(entry)
            );
        }
        assert_eq!(
            VANILLA_DEBUG_SUBSCRIPTION_TYPES[0].constant_name,
            "DEDICATED_SERVER_TICK_TIME"
        );
        assert_eq!(
            VANILLA_DEBUG_SUBSCRIPTION_TYPES[0].resource_id,
            "minecraft:dedicated_server_tick_time"
        );
        assert!(!VANILLA_DEBUG_SUBSCRIPTION_TYPES[0].has_value_codec);
        assert_eq!(VANILLA_DEBUG_SUBSCRIPTION_TYPES[0].expire_after_ticks, 0);
        assert!(VANILLA_DEBUG_SUBSCRIPTION_TYPES[6].has_value_codec);
        assert_eq!(VANILLA_DEBUG_SUBSCRIPTION_TYPES[6].expire_after_ticks, 100);
        assert_eq!(VANILLA_DEBUG_SUBSCRIPTION_TYPES[9].expire_after_ticks, 200);
        assert_eq!(VANILLA_DEBUG_SUBSCRIPTION_TYPES[14].expire_after_ticks, 200);
        assert_eq!(
            VANILLA_DEBUG_SUBSCRIPTION_TYPES[15].constant_name,
            "GAME_EVENTS"
        );
        assert_eq!(
            VANILLA_DEBUG_SUBSCRIPTION_TYPES[15].resource_id,
            "minecraft:game_events"
        );
        assert_eq!(VANILLA_DEBUG_SUBSCRIPTION_TYPES[15].expire_after_ticks, 60);
        assert_eq!(vanilla_debug_subscription_type_by_id(-1), None);
        assert_eq!(vanilla_debug_subscription_type_by_id(16), None);
    }

    #[test]
    fn production_sources_do_not_redeclare_debug_subscription_ids() {
        fn visit(directory: &Path, violations: &mut Vec<String>) {
            for entry in fs::read_dir(directory).unwrap() {
                let path = entry.unwrap().path();
                if path.is_dir() {
                    visit(&path, violations);
                    continue;
                }
                if path.extension().and_then(|value| value.to_str()) != Some("rs") {
                    continue;
                }
                let display = path.to_string_lossy();
                if display.ends_with("/debug_subscription_types.rs")
                    || display.ends_with("/tests.rs")
                    || display.contains("/tests/")
                {
                    continue;
                }
                let source = fs::read_to_string(&path).unwrap();
                let production = source.split("#[cfg(test)]").next().unwrap_or(&source);
                if production.contains("DEBUG_SUBSCRIPTION_DEDICATED_SERVER_TICK_TIME_ID: i32 =") {
                    violations.push(display.to_string());
                }
            }
        }
        let mut violations = Vec::new();
        visit(
            Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap(),
            &mut violations,
        );
        assert!(
            violations.is_empty(),
            "parallel debug subscription id owners: {violations:?}"
        );
    }
}

